static const size_t BidiBracketsCount = 128;

UnicodeBidiClass BidiClassProperty(Uchar32 cp)
{
    size_t lo = 0, hi = BidiBcRangesCount;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        const BidiRange8 *r = &BidiBcRanges[mid];
        if (cp < r->start) {
            hi = mid;
        } else if (cp > r->end) {
            lo = mid + 1u;
        } else {
            return (UnicodeBidiClass)r->value;
        }
    }
    return RoboUBcL;
}

int BidiBracketLookup(Uchar32 cp, uint32_t *pairOut, int *isOpenOut)
{
    size_t lo = 0, hi = BidiBracketsCount;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        const BidiBracket *b = &BidiBrackets[mid];
        if (cp < b->cp) {
            hi = mid;
        } else if (cp > b->cp) {
            lo = mid + 1u;
        } else {
            if (pairOut) {
                *pairOut = b->pair;
            }
            if (isOpenOut) {
                *isOpenOut = (int)b->isOpen;
            }
            return 1;
        }
    }
    return 0;
}

